#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__device__ __forceinline__ void combine_pair(float &m, float &s, float pm, float ps) {
    if (ps == 0.0f) return;
    if (s == 0.0f) { m = pm; s = ps; return; }
    if (pm > m) {
        s = s * __expf(m - pm) + ps;
        m = pm;
    } else {
        s += ps * __expf(pm - m);
    }
}

template <typename scalar_t>
__global__ void softmax_warp_kernel(const scalar_t* __restrict__ x,
                                    scalar_t* __restrict__ y,
                                    int N, int D) {
    int row = blockIdx.x;
    int lane = threadIdx.x; // launched with exactly one warp
    if (row >= N) return;
    const scalar_t* __restrict__ row_x = x + (long long)row * D;
    scalar_t* __restrict__ row_y = y + (long long)row * D;

    float m = -FLT_MAX;
    float s = 0.0f;
    for (int col = lane; col < D; col += 32) {
        float v = static_cast<float>(row_x[col]);
        if (v > m) {
            s = s * __expf(m - v) + 1.0f;
            m = v;
        } else {
            s += __expf(v - m);
        }
    }

    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        float pm = __shfl_xor_sync(mask, m, offset);
        float ps = __shfl_xor_sync(mask, s, offset);
        combine_pair(m, s, pm, ps);
    }

    float inv_s = 1.0f / s;
    for (int col = lane; col < D; col += 32) {
        float v = static_cast<float>(row_x[col]);
        row_y[col] = static_cast<scalar_t>(__expf(v - m) * inv_s);
    }
}

template <typename scalar_t, int BLOCK>
__global__ void softmax_block_kernel(const scalar_t* __restrict__ x,
                                     scalar_t* __restrict__ y,
                                     int N, int D) {
    int row = blockIdx.x;
    int tid = threadIdx.x;
    if (row >= N) return;
    const scalar_t* __restrict__ row_x = x + (long long)row * D;
    scalar_t* __restrict__ row_y = y + (long long)row * D;

    float m = -FLT_MAX;
    float s = 0.0f;
    for (int col = tid; col < D; col += BLOCK) {
        float v = static_cast<float>(row_x[col]);
        if (v > m) {
            s = s * __expf(m - v) + 1.0f;
            m = v;
        } else {
            s += __expf(v - m);
        }
    }

    __shared__ float sm[BLOCK];
    __shared__ float ss[BLOCK];
    sm[tid] = m;
    ss[tid] = s;
    __syncthreads();

    for (int stride = BLOCK >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            float pm = sm[tid + stride];
            float ps = ss[tid + stride];
            combine_pair(m, s, pm, ps);
            sm[tid] = m;
            ss[tid] = s;
        }
        __syncthreads();
